hannel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/7rNv1kRCUTU/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2026-06-06T16:00:25Z","viewCount":70239,"durationSeconds":5370,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
